// Writes a size tier into a copy of the leptoskit tier shell
// (`arena/apps/leptoskit/tier`): one Rust module per screen under
// `tier_app/src/routes/`, and `tier_app/src/routes.rs`, which declares them
// and holds the navigator. Screens use only View, Text, Button, TextInput,
// and ScrollView, the components the generated macOS, iOS, and Android apps
// draw.

import {
	type CounterScreen,
	type DetailScreen,
	type FormScreen,
	type ListScreen,
	quoted,
	type Screen,
	type TierApp,
	type TierEmitter,
} from "../tiers.ts";

const HEADER =
	"//! Generated by benchmarks/scripts/arena/emit/leptoskit.ts. Do not edit.\n";

/** `counter001` → `Counter001`, the screen's `Route` variant. */
function variant(screen: Screen): string {
	return screen.id[0].toUpperCase() + screen.id.slice(1);
}

/** Whether the screen keeps state in the model. */
function stateful(screen: Screen): boolean {
	return screen.kind === "counter" || screen.kind === "form";
}

/** The `Back` button every screen gets when the app has a menu. */
function back(withMenu: boolean): string {
	return withMenu
		? `\n\t\t\tButton("Back")\n\t\t\t\t.class("h-11 px-4")\n\t\t\t\t.on_press(app.navigator(Route::Home)),`
		: "";
}

function counter(screen: CounterScreen, withMenu: boolean): string {
	return `${HEADER}
use leptoskit::prelude::*;

${withMenu ? "use super::Route;\n" : ""}use crate::Store;

/// This screen's state.
#[derive(Debug, Default)]
pub struct State {
	count: i64,
}

/// ${screen.title}
pub fn screen(app: &Store, state: &State) -> Element {
	let add_app = app.clone();
	View()
		.class("flex-1 gap-4 p-6")
		.children([${back(withMenu)}
			Text(${quoted(screen.title)}).class("text-2xl font-bold"),
			Text(format!("Count: {}", state.count)).class("text-xl"),
			Button(${quoted(`Add ${screen.step}`)})
				.class("h-11 rounded-lg bg-indigo-500 px-4 text-white")
				.on_press(move || add_app.update(|model| model.${screen.id}.count += ${screen.step})),
		])
}
`;
}

function list(screen: ListScreen, withMenu: boolean): string {
	const rows = screen.rows.map((row) =>
		`\t\t\t\tView().class("py-2").children([\n\t\t\t\t\tText(${
			quoted(row.title)
		}).class("text-base font-semibold"),\n\t\t\t\t\tText(${
			quoted(row.subtitle)
		}).class("text-sm"),\n\t\t\t\t]),`
	).join("\n");
	return `${HEADER}
use leptoskit::prelude::*;
${withMenu ? "\nuse super::Route;\nuse crate::Store;\n" : ""}
/// ${screen.title}
pub fn screen(${withMenu ? "app: &Store" : ""}) -> Element {
\tView().class("flex-1").children([${back(withMenu)}
		Text(${quoted(screen.title)}).class("px-6 pt-6 text-2xl font-bold"),
		ScrollView().class("flex-1").child(View().class("px-6").children([
${rows}
		])),
	])
}
`;
}

function form(screen: FormScreen, withMenu: boolean): string {
	const count = screen.fields.length;
	const inputs = screen.fields.map((field, index) =>
		`\t\t\tText(${quoted(field.label)}),
			TextInput()
				.class("h-10 px-2")
				.placeholder(${quoted(field.label)})
				.value(state.values[${index}].clone())
				.on_change({
					let app = app.clone();
					move |text| app.update(|model| model.${screen.id}.values[${index}] = text.to_owned())
				}),`
	).join("\n");
	const checks = screen.fields.map((field, index) =>
		`\t\t\tif values[${index}].chars().count() < ${field.minLength} {
				problems.push(${
			quoted(`${field.label} needs at least ${field.minLength} characters`)
		}.to_owned());
			}`
	).join("\n");
	return `${HEADER}
use leptoskit::prelude::*;

${withMenu ? "use super::Route;\n" : ""}use crate::Store;

/// This screen's state.
#[derive(Debug, Default)]
pub struct State {
	values: [String; ${count}],
	messages: Vec<String>,
}

/// ${screen.title}
pub fn screen(app: &Store, state: &State) -> Element {
	let submit_app = app.clone();
	View()
		.class("flex-1 gap-3 p-6")
		.children([${back(withMenu)}
			Text(${quoted(screen.title)}).class("text-2xl font-bold"),
${inputs}
			Button(${quoted(screen.submitLabel)})
				.class("h-11 rounded-lg bg-indigo-500 px-4 text-white")
				.on_press(move || submit_app.update(|model| submit(&mut model.${screen.id}))),
		])
		.children(state.messages.iter().map(|message| Text(message.clone())))
}

/// Checks every field, then shows the problems or the saved values.
fn submit(state: &mut State) {
	let values = &state.values;
	let mut problems = Vec::new();
${checks}
	state.messages = if problems.is_empty() {
		vec![format!("Saved: {}", values.join(", "))]
	} else {
		problems
	};
}
`;
}

function detail(screen: DetailScreen, withMenu: boolean): string {
	const paragraphs = screen.paragraphs.map((paragraph) =>
		`\t\t\t\tText(${quoted(paragraph)}),`
	).join("\n");
	return `${HEADER}
use leptoskit::prelude::*;
${withMenu ? "\nuse super::Route;\nuse crate::Store;\n" : ""}
/// ${screen.title}
pub fn screen(${withMenu ? "app: &Store" : ""}) -> Element {
\tView().class("flex-1").children([${back(withMenu)}
		ScrollView().class("flex-1").child(View().class("gap-4 p-6").children([
			Text(${quoted(screen.title)}).class("text-2xl font-bold"),
${paragraphs}
		])),
	])
}
`;
}

function module(screen: Screen, withMenu: boolean): string {
	switch (screen.kind) {
		case "counter":
			return counter(screen, withMenu);
		case "list":
			return list(screen, withMenu);
		case "form":
			return form(screen, withMenu);
		case "detail":
			return detail(screen, withMenu);
	}
}

/** The call that renders one screen from the locked model. */
function call(screen: Screen, withMenu: boolean): string {
	if (stateful(screen)) return `${screen.id}::screen(app, &model.${screen.id})`;
	return withMenu ? `${screen.id}::screen(app)` : `${screen.id}::screen()`;
}

function navigator(app: TierApp): string {
	const withMenu = app.screens.length > 1;
	const modules = app.screens.map((screen) => `pub mod ${screen.id};`).join(
		"\n",
	);
	const states = app.screens.filter(stateful).map((screen) =>
		`\tpub ${screen.id}: ${screen.id}::State,`
	)
		.join("\n");
	if (!withMenu) {
		const [only] = app.screens;
		return `${HEADER}//!
//! A single screen, rendered directly.

${modules}

use leptoskit::prelude::Element;

use crate::Store;

/// Everything the app renders from.
#[derive(Debug, Default)]
pub struct Model {
${states}
}

/// The app's only screen.
pub fn screen(app: &Store) -> Element {
	let model = app.read();
	${call(only, false)}
}
`;
	}

	const variants = app.screens.map((screen) => `\t${variant(screen)},`).join(
		"\n",
	);
	const arms = app.screens.map((screen) =>
		`\t\tRoute::${variant(screen)} => ${call(screen, true)},`
	).join("\n");
	const buttons = app.screens.map((screen) =>
		`\t\t\tButton(${
			quoted(screen.title)
		}).class("h-11 px-4").on_press(app.navigator(Route::${variant(screen)})),`
	).join("\n");
	return `${HEADER}//!
//! The navigator: the current route is state, with no routing library.

${modules}

use leptoskit::prelude::*;

use crate::Store;

/// Every screen, and the home menu.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Route {
	#[default]
	Home,
${variants}
}

/// Everything the app renders from.
#[derive(Debug, Default)]
pub struct Model {
	pub route: Route,
${states}
}

impl Store {
	/// A press handler that moves to \`route\`.
	pub fn navigator(&self, route: Route) -> impl Fn() + Send + Sync + 'static {
		let app = self.clone();
		move || app.update(|model| model.route = route)
	}
}

/// The screen for the current route.
pub fn screen(app: &Store) -> Element {
	let model = app.read();

	match model.route {
		Route::Home => home(app),
${arms}
	}
}

/// The home menu: one button per screen.
fn home(app: &Store) -> Element {
	ScrollView().class("flex-1").child(View().class("gap-2 p-6").children([
		Text(${quoted(app.title)}).class("text-3xl font-bold"),
${buttons}
	]))
}
`;
}

export const emitter: TierEmitter = {
	framework: "leptoskit",
	async emit(app: TierApp, projectDir: string): Promise<void> {
		const withMenu = app.screens.length > 1;
		const routes = `${projectDir}/tier_app/src/routes`;
		await Deno.mkdir(routes, { recursive: true });
		await Deno.writeTextFile(
			`${projectDir}/tier_app/src/routes.rs`,
			navigator(app),
		);
		for (const screen of app.screens) {
			await Deno.writeTextFile(
				`${routes}/${screen.id}.rs`,
				module(screen, withMenu),
			);
		}
	},
};
